// ORACLE STUB (not upstream source): in-memory stand-in for jiti's module
// loader. Factories are pre-registered on globalThis.__extFactoryRegistry by
// the oracle scripts; module-not-found mimics a resolution failure. Disclosed
// in the extensions port report (seam O-3).
export function createJiti() {
  return {
    async import(specifier, _opts) {
      const registry = globalThis.__extFactoryRegistry ?? {};
      if (!(specifier in registry)) {
        throw new Error(`Cannot find module '${specifier}'`);
      }
      return registry[specifier];
    },
  };
}
